package tokens

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// notEdit is the sentence that tells a person not to edit a generated file,
// built in two parts so no Go file of the repository carries the phrase a lint
// reads as a generated-file header (cli.process.1).
const notEdit = "Do not " + "edit"

// pair is a colour for each mode, as palette.json writes it: the shape
// host/term reads as its Ground.
type pair struct {
	Light string `json:"light"`
	Dark  string `json:"dark"`
}

// header is the line each generated file opens with: the generator, its
// version and the one document it reads, so a person who opens the file is told
// not to edit it and by what it is written (supply.provenance.4,
// gates.own-rules.3).
func header() string {
	return fmt.Sprintf("Generated by gragas-dev tokens v%s from %s. %s: make gen writes it, and make gen-check fails on a hand edit.", Version, File, notEdit)
}

// Sections of the custom properties, as the name each is given there.
func propertyName(section string) string {
	return map[string]string{
		"grounds": "ground", "text": "text", "standing": "standing",
		"marks": "mark", "observations": "observation", "parts": "",
	}[section]
}

// property is the name of a custom property: --gr-<kind>-<name>, or --gr-<name>
// for the parts, which are named for what they are.
func property(kind, n string) string {
	if kind == "" {
		return "--" + Prefix + "-" + n
	}
	return "--" + Prefix + "-" + kind + "-" + n
}

// decl is one custom property and its value.
type decl struct{ name, value string }

// modeDecls are the properties whose value differs by mode, in the order they
// are written.
func (d Document) modeDecls(m Mode) []decl {
	var out []decl
	for _, s := range d.colourSections() {
		for _, n := range sortedKeys(s.roles) {
			out = append(out, decl{property(propertyName(s.name), n), s.roles[n].In(m)})
		}
	}
	for _, n := range sortedKeys(d.Shadow) {
		out = append(out, decl{property("shadow", n), d.Shadow[n].In(m)})
	}
	return out
}

// scaleDecls are the properties that have one value in both modes.
func (d Document) scaleDecls() []decl {
	var out []decl
	for _, s := range []struct {
		kind  string
		scale map[string]string
	}{{"space", d.Spacing}, {"radius", d.Radius}} {
		for _, n := range sortedKeys(s.scale) {
			out = append(out, decl{property(s.kind, n), s.scale[n]})
		}
	}
	return append(out, decl{property("font", "sans"), d.Fonts.Sans}, decl{property("font", "mono"), d.Fonts.Mono})
}

func writeBlock(b *strings.Builder, selectors []string, indent string, scheme Mode, ds ...[]decl) {
	for i, s := range selectors {
		sep := ",\n"
		if i == len(selectors)-1 {
			sep = " {\n"
		}
		b.WriteString(indent + s + sep)
	}
	b.WriteString(indent + "  color-scheme: " + string(scheme) + ";\n")
	for _, list := range ds {
		for _, x := range list {
			b.WriteString(indent + "  " + x.name + ": " + x.value + ";\n")
		}
	}
	b.WriteString(indent + "}\n")
}

// CSS is the custom properties file: light under :root and :host, dark when
// the system asks for it and the host has not chosen light, and dark when the
// host chooses it, the one scoping method of every consumer (web.tokens.15).
// The shadow DOM of the element reads the same names through :host, and a host
// page re-themes by setting any of them.
func (d Document) CSS() []byte {
	var b strings.Builder
	b.WriteString("/* " + header() + " */\n\n")
	writeBlock(&b, []string{":root", ":host"}, "", Light, d.modeDecls(Light), d.scaleDecls())
	b.WriteString("\n@media (prefers-color-scheme: dark) {\n")
	writeBlock(&b, []string{`:root:not([data-theme="light"])`, `:host(:not([data-theme="light"]))`}, "  ", Dark, d.modeDecls(Dark))
	b.WriteString("}\n\n")
	writeBlock(&b, []string{`:root[data-theme="dark"]`, `:host([data-theme="dark"])`}, "", Dark, d.modeDecls(Dark))
	return []byte(b.String())
}

// Theme is the Tailwind 4 theme as CSS: every colour, radius, shadow, font and
// breakpoint the document names, each reading the custom property of CSS(), so
// the utilities follow the mode and a host's override. It is plain CSS and
// runs no Tailwind. Spacing is Tailwind's one base, the document's first step,
// and each other step a named one. The breakpoints are literals of the theme
// alone: a media query cannot read a custom property, so CSS() holds none.
func (d Document) Theme() []byte {
	var b strings.Builder
	b.WriteString("/* " + header() + " */\n\n@theme inline {\n")
	for _, s := range d.colourSections() {
		for _, n := range sortedKeys(s.roles) {
			utility := n
			if k := propertyName(s.name); k != "" {
				utility = k + "-" + n
			}
			fmt.Fprintf(&b, "  --color-%s: var(%s);\n", utility, property(propertyName(s.name), n))
		}
	}
	fmt.Fprintf(&b, "  --spacing: var(%s);\n", property("space", "1"))
	for _, n := range sortedKeys(d.Spacing) {
		if n != "1" {
			fmt.Fprintf(&b, "  --spacing-%s: var(%s);\n", n, property("space", n))
		}
	}
	for _, n := range sortedKeys(d.Radius) {
		fmt.Fprintf(&b, "  --radius-%s: var(%s);\n", n, property("radius", n))
	}
	for _, n := range sortedKeys(d.Shadow) {
		fmt.Fprintf(&b, "  --shadow-%s: var(%s);\n", n, property("shadow", n))
	}
	fmt.Fprintf(&b, "  --font-sans: var(%s);\n  --font-mono: var(%s);\n", property("font", "sans"), property("font", "mono"))
	for _, n := range breakpointNames() {
		fmt.Fprintf(&b, "  --breakpoint-%s: %s;\n", n, d.Breakpoints[n])
	}
	b.WriteString("}\n")
	return []byte(b.String())
}

// paletteDoc is the terminal's palette file: the shape host/term reads (the
// ground of the page and a colour for each text role) and, beside it, the
// standing, mark and observation roles the same document names, so web and
// terminal share their role names (web.tokens.19). host/term ignores a key it
// does not read, and "$generated" names the generator.
type paletteDoc struct {
	Generated    string          `json:"$generated"`
	Grounds      pair            `json:"grounds"`
	Text         map[string]pair `json:"text"`
	Standing     map[string]pair `json:"standing"`
	Marks        map[string]pair `json:"marks"`
	Observations map[string]pair `json:"observations"`
}

func pairs(m map[string]Colour) map[string]pair {
	out := make(map[string]pair, len(m))
	for n, c := range m {
		out[n] = pair{Light: c.Light, Dark: c.Dark}
	}
	return out
}

// Palette is host/term's palette.json. The page ground is the one the terminal
// draws on. The error is a document with no page ground.
func (d Document) Palette() ([]byte, error) {
	page, ok := d.Grounds["page"]
	if !ok {
		return nil, fmt.Errorf("%w: grounds.page: the ground the terminal draws on is missing", ErrDocument)
	}
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetIndent("", "  ")
	err := enc.Encode(paletteDoc{
		Generated: fmt.Sprintf("gragas-dev tokens v%s from %s: %s", Version, File, strings.ToLower(notEdit)),
		Grounds:   pair{Light: page.Light, Dark: page.Dark},
		Text:      pairs(d.Text), Standing: pairs(d.Standing),
		Marks: pairs(d.Marks), Observations: pairs(d.Observations),
	})
	return b.Bytes(), err
}
